    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int s = (int) in.nval;
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        Result res = solve(n, edges, s);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.reachable.size(); i++) sb.append(res.reachable.get(i)).append(i + 1 < res.reachable.size() ? " " : "");
        sb.append("\n").append(res.added.size()).append("\n");
        for (int[] e : res.added) sb.append(e[0]).append(" ").append(e[1]).append("\n");
        System.out.print(sb);
    }
}
